"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type Mode = "day" | "nocturne"

/** The three variants that are a real switch, each with the scene change it asks the page for (a View Transition type). */
const SCENES = { stop: "ot-dissolve", dimmer: "ot-dim", noon: "ot-fall" } as const

type ModeToggleProps = Omit<React.ComponentProps<"button">, "children" | "onChange"> & {
  /**
   * Eight ways to draw the same choice. eclipse: a disc slides over a ring; horizon: the dot rises or sets; words: the chosen word,
   * drawn like a select, rolls to the other; fermata: the arc is an eyelid; sentence: "Read by light." and "Read by night.";
   * knockout: "midday" and "midnight", the second half reversed out of the ink as night falls; hour: 12:00 and 00:00, the hour
   * turning forward whichever way you go. Three are switches with a scene change of their own: stop: "Day" over "Night", the full
   * stop setting from one to the other (the page dissolves); dimmer: "Night", its letters taking the ink in turn (the page's
   * light is lowered or raised); noon: "Noon" and "Moon", one letter apart, the initial falling or rising (night falls over the page).
   */
  variant?: "eclipse" | "horizon" | "words" | "fermata" | "sentence" | "knockout" | "hour" | "stop" | "dimmer" | "noon"
  /** The mode, when you hold it (controlled). */
  mode?: Mode
  /** The mode to start in, when the toggle holds it. */
  defaultMode?: Mode
  /** Called with the mode the person chose, and the click that chose it. The toggle applies nothing to the page. */
  onModeChange?: (mode: Mode, event: React.MouseEvent<HTMLButtonElement>) => void
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/**
 * The day and night toggle. One button, on when it is night, drawn ten ways: a disc sliding across a ring, a dot above or
 * below a hairline, a word on a hairline that rolls to the other, the fermata as an eye, a sentence whose last word rolls,
 * midday turning to midnight in an ink block, a clock turning from noon to midnight, a full stop setting from Day to Night,
 * a word that takes the ink letter by letter, or Noon turning to Moon. It only reports the choice; the page applies it, for
 * instance `document.documentElement.dataset.mode = mode`. Stop, dimmer and noon carry `data-scene`, the View Transition
 * type their scene change is drawn for; the appearance hook passes it on.
 */
function ModeToggle({ variant = "eclipse", mode, defaultMode = "day", onModeChange, onClick, onPointerLeave, onBlur, className, "data-force": force, "aria-label": label, ...props }: ModeToggleProps) {
  const [own, setOwn] = React.useState<Mode>(defaultMode)
  const now = mode ?? own
  const scene = variant in SCENES ? SCENES[variant as keyof typeof SCENES] : undefined
  // After a press the switch rests: its pointing sketch waits until the pointer leaves or focus moves on.
  const [rested, setRested] = React.useState(false)
  // The hour only turns once the mode has changed, so nothing rolls on first paint.
  const [start] = React.useState(now)
  const [turned, setTurned] = React.useState(false)
  if (!turned && now !== start) setTurned(true)
  return (
    <button
      type="button"
      data-slot="mode-toggle"
      data-variant={variant}
      data-force={force}
      data-turned={variant === "hour" && turned ? "" : undefined}
      data-scene={scene}
      data-rested={scene && rested ? "" : undefined}
      // A scene change swaps what is under the pointer; only a real leave ends the rest.
      onPointerLeave={(e) => { if (!CSS.supports("selector(:active-view-transition)") || !document.documentElement.matches(":active-view-transition")) setRested(false); onPointerLeave?.(e) }}
      onBlur={(e) => { setRested(false); onBlur?.(e) }}
      role={scene ? "switch" : undefined}
      aria-checked={scene ? now === "nocturne" : undefined}
      aria-pressed={scene ? undefined : now === "nocturne"}
      aria-label={label ?? "Night mode"}
      className={cn("ot-mode", className)}
      onClick={(e) => {
        onClick?.(e)
        if (e.defaultPrevented) return
        setRested(true)
        const next: Mode = now === "nocturne" ? "day" : "nocturne"
        if (mode === undefined) setOwn(next)
        onModeChange?.(next, e)
      }}
      {...props}
    >
      <span className="ot-mode-art" aria-hidden="true">
        {variant === "stop" ? (
          <>
            <span data-for="day">Day</span>
            <span data-for="nocturne">Night</span>
          </>
        ) : variant === "dimmer" ? (
          Array.from("Night", (letter, i) => <span key={i} style={{ "--i": i } as React.CSSProperties}>{letter}</span>)
        ) : variant === "noon" ? (
          <>
            <span className="ot-mode-initial"><span>N</span><span>M</span></span>oon
          </>
        ) : variant === "words" ? (
          <span className="ot-mode-roll">
            <span>day</span>
            <span>night</span>
          </span>
        ) : variant === "sentence" ? (
          <>
            Read by{" "}
            <span className="ot-mode-state">
              <span>light</span>
              <span>night</span>
            </span>
            <span className="ot-mode-stop" />
          </>
        ) : variant === "knockout" ? (
          <>
            <span className="ot-mode-mid">mid</span>
            <span className="ot-mode-block">
              <span>day</span>
              <span>night</span>
            </span>
          </>
        ) : variant === "hour" ? (
          <span className="ot-mode-hour">
            <span className="ot-mode-digit"><span>1</span><span>0</span></span>
            <span className="ot-mode-digit"><span>2</span><span>0</span></span>
            <span className="ot-mode-min">:00</span>
          </span>
        ) : null}
      </span>
    </button>
  )
}

export { ModeToggle, type ModeToggleProps, type Mode }

@layer components {
  @property --ot-mode-x { syntax: "<length>"; inherits: false; initial-value: 0px; }
  /* ── ot-mode ── the day and night toggle: one button, on at night, drawn ten ways.
     Drawings read aria-pressed (the stop, dimmer and noon switches read aria-checked), one source of truth. */
  .ot-mode {
    --dir: 1;
    appearance: none; border: 0; background: none; font: inherit; color: var(--ot-graphite);
    display: inline-flex; align-items: center; vertical-align: middle; cursor: pointer;
    padding: 0.4em; margin: -0.4em; /* a hit area larger than the drawing, without moving anything */
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ot-allegro) var(--ot-breath);
  }
  .ot-mode:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  .ot-mode:is(:hover, [data-force~="hover"]) { color: var(--ot-ink); }
  .ot-mode:focus-visible, .ot-mode[data-force~="focus"] { outline: var(--ot-stroke) solid var(--ot-accent); outline-offset: 0; }
  .ot-mode[data-force~="focus"] { outline-offset: 0; }
  .ot-mode:disabled { opacity: 0.55; cursor: not-allowed; }
  .ot-mode-art { position: relative; display: block; flex: none; }
  .ot-mode-art::before, .ot-mode-art::after { content: ""; position: absolute; }

  /* eclipse: a ring, and a disc filling it that a mask bites into. Day is the whole sun; night is a crescent on the moon's rim.
     The disc meets the ring: with a gap between them, day read as a checked radio. */
  .ot-mode[data-variant="eclipse"] .ot-mode-art { width: 1.5em; height: 1.5em; border-radius: 50%; border: var(--ot-stroke) solid currentColor; box-sizing: border-box; }
  .ot-mode[data-variant="eclipse"] .ot-mode-art::before {
    inset: 0; border-radius: 50%; background: currentColor;
    --ot-mode-x: 1.9em;
    -webkit-mask: radial-gradient(circle at calc(50% + var(--dir) * var(--ot-mode-x)) calc(50% - var(--ot-mode-x)), transparent 0.56em, #000 calc(0.56em + 0.6px));
    mask: radial-gradient(circle at calc(50% + var(--dir) * var(--ot-mode-x)) calc(50% - var(--ot-mode-x)), transparent 0.56em, #000 calc(0.56em + 0.6px));
    transition: --ot-mode-x var(--ot-andante) var(--ot-breath);
  }
  .ot-mode[data-variant="eclipse"][aria-pressed="true"] .ot-mode-art::before { --ot-mode-x: 0.34em; }

  /* horizon: a hairline, and a dot that stands above it by day, sets below it at night, and empties as it goes. */
  .ot-mode[data-variant="horizon"] .ot-mode-art { width: 2.2em; height: 1.8em; }
  .ot-mode[data-variant="horizon"] .ot-mode-art::before { inset: 50% 0 auto; border-top: var(--ot-hairline) solid currentColor; }
  .ot-mode[data-variant="horizon"] .ot-mode-art::after {
    left: calc(50% - 0.25em); top: 0.05em; width: 0.5em; height: 0.5em; border-radius: 50%;
    box-shadow: inset 0 0 0 0.25em currentColor;
    transition: top var(--ot-andante) var(--ot-spiccato), box-shadow var(--ot-andante) var(--ot-exhale);
  }
  .ot-mode[data-variant="horizon"][aria-pressed="true"] .ot-mode-art::after { top: 1.25em; box-shadow: inset 0 0 0 var(--ot-stroke) currentColor; }

  /* fermata: the sign as an eye. The arc is the lid over the dot; at night it comes down and closes over it. */
  .ot-mode[data-variant="fermata"] .ot-mode-art { width: 1.9em; height: 1.3em; }
  .ot-mode[data-variant="fermata"] .ot-mode-art::before {
    inset: 0 0 auto; height: 0.8em; border-top: var(--ot-stroke) solid currentColor; border-radius: 50% 50% 0 0 / 100% 100% 0 0;
    transition: height var(--ot-moderato) var(--ot-exhale), top var(--ot-moderato) var(--ot-exhale);
  }
  .ot-mode[data-variant="fermata"] .ot-mode-art::after {
    left: calc(50% - 0.21em); top: 0.72em; width: 0.42em; height: 0.42em; border-radius: 50%; background: currentColor;
    transition: scale var(--ot-moderato) var(--ot-exhale);
  }
  .ot-mode[data-variant="fermata"][aria-pressed="true"] .ot-mode-art::before { height: 0; top: 0.93em; }
  .ot-mode[data-variant="fermata"][aria-pressed="true"] .ot-mode-art::after { scale: 1 0.14; }

  /* words: the choice as a word in a sentence, drawn like a select's. The word you're reading by stands in the italic on a hairline,
     with ↕ where a select has ↓: the other word is above or below it, not in a list. Choosing rolls it the way the sun goes,
     everything down into night and up into day, and the line narrows or widens to the new word. */
  .ot-mode[data-variant="words"] { align-items: baseline; vertical-align: baseline; }
  .ot-mode[data-variant="words"] .ot-mode-art { display: inline-flex; align-items: baseline; }
  .ot-mode-roll {
    display: inline-grid; align-items: baseline; overflow: clip; interpolate-size: allow-keywords;
    padding: 0 0.6em 0.1em 0; /* a select's: the arrow sits in the end padding, the hairline under the descenders */
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1.2; color: var(--ot-ink);
    background: linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / calc(100% - 0.6em) var(--ot-hairline);
  }
  .ot-mode-roll:is([dir="rtl"], [dir="rtl"] *) { padding-inline: 0.6em 0; background-position: 100% 100%; }
  .ot-mode-roll > * {
    grid-area: 1 / 1; justify-self: start; white-space: nowrap;
    transition: translate var(--ot-moderato) var(--ot-breath), opacity var(--ot-moderato) var(--ot-breath), inline-size var(--ot-moderato) var(--ot-breath);
  }
  /* The word that isn't chosen takes no width and waits out of the clip: day below the line, night above it. */
  .ot-mode[aria-pressed="true"] .ot-mode-roll > :first-child { translate: 0 130%; opacity: 0; inline-size: 0; }
  .ot-mode[aria-pressed="false"] .ot-mode-roll > :last-child { translate: 0 -130%; opacity: 0; inline-size: 0; }
  .ot-mode[data-variant="words"] .ot-mode-art::after {
    content: "↕" / ""; inset-inline-end: 0; bottom: 0.3em; /* in the roll's end padding, where a select's arrow sits in its own */
    font-family: var(--ot-voice); font-size: 0.72em; line-height: 1; color: var(--ot-pencil); pointer-events: none;
    transition: translate var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  .ot-mode[data-variant="words"]:is(:hover, [data-force~="hover"]) .ot-mode-roll { background-image: linear-gradient(var(--ot-ink), var(--ot-ink)); }
  .ot-mode[data-variant="words"]:is(:hover, [data-force~="hover"]) .ot-mode-art::after { color: var(--ot-ink); translate: 0 var(--nudge, -2px); }
  .ot-mode[data-variant="words"][aria-pressed="true"]:is(:hover, [data-force~="hover"]) { --nudge: 2px; } /* toward the word you would get: night waits above, day below */

  /* sentence: "Read by light." and "Read by night." The last word rolls the way the sun goes: light rises in from below, night sets in from above. The full stop is a dot by day and a ring by night. */
  .ot-mode[data-variant="sentence"] .ot-mode-art { white-space: nowrap; }
  .ot-mode-state {
    display: inline-grid; vertical-align: baseline; overflow: clip;
    padding: 0.12em 0.14em 0.24em; margin-block: -0.12em -0.24em; margin-inline: -0.08em -0.14em;
    font-family: var(--ot-expression); font-style: italic; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1; color: var(--ot-ink);
    background: linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0.14em calc(100% - 0.1em) / calc(100% - 0.28em) var(--ot-hairline);
    transition: background-color var(--ot-moderato);
  }
  .ot-mode-state > span { grid-area: 1 / 1; transition: translate var(--ot-moderato) var(--ot-breath), opacity var(--ot-moderato) var(--ot-breath); }
  .ot-mode[aria-pressed="true"] .ot-mode-state > :first-child { translate: 0 110%; opacity: 0; }
  .ot-mode[aria-pressed="false"] .ot-mode-state > :last-child { translate: 0 -110%; opacity: 0; }
  .ot-mode:is(:hover, [data-force~="hover"]) .ot-mode-state { background-image: linear-gradient(var(--ot-ink), var(--ot-ink)); }
  .ot-mode-stop {
    display: inline-block; width: max(0.22em, 5px); height: max(0.22em, 5px); margin-inline-start: 0.24em; border-radius: 50%;
    box-shadow: inset 0 0 0 0.5em currentColor; transition: box-shadow var(--ot-andante) var(--ot-exhale);
  }
  .ot-mode[aria-pressed="true"] .ot-mode-stop { box-shadow: inset 0 0 0 var(--ot-hairline) currentColor; }

  /* knockout: after "the uncreative", where part of a word is reversed out of an ink block. "mid" stays heavy roman on the paper;
     the half you chose is the italic. By day it reads midday. At night the ink falls over the second half from above, the way
     nocturne falls over the page, and night reverses out of it; at dawn the ink lifts. Pointing lets a sliver fall, or lifts it a little. */
  .ot-mode[data-variant="knockout"] { align-items: baseline; vertical-align: baseline; color: var(--ot-ink); }
  .ot-mode[data-variant="knockout"] .ot-mode-art { display: inline-flex; align-items: baseline; white-space: nowrap; }
  .ot-mode-mid { font-weight: 760; letter-spacing: -0.03em; }
  .ot-mode-block {
    --fall: 0; position: relative; isolation: isolate; display: inline-grid; align-items: baseline; overflow: clip; interpolate-size: allow-keywords;
    padding: 0.04em 0.16em 0.1em 0.06em; margin-block: -0.04em -0.1em;
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1.05;
    color: var(--ot-ink); transition: color var(--ot-moderato) var(--ot-breath);
  }
  .ot-mode-block::before {
    content: ""; position: absolute; inset: 0; z-index: -1; background: var(--ot-ink);
    scale: 1 var(--fall); transform-origin: 50% 0; transition: scale var(--ot-moderato) var(--ot-breath);
  }
  .ot-mode-block > * { grid-area: 1 / 1; justify-self: start; transition: opacity var(--ot-moderato) var(--ot-breath), inline-size var(--ot-moderato) var(--ot-breath); }
  .ot-mode[data-variant="knockout"][aria-pressed="true"] .ot-mode-block { --fall: 1; color: var(--ot-paper); }
  .ot-mode[data-variant="knockout"][aria-pressed="true"] .ot-mode-block > :first-child,
  .ot-mode[data-variant="knockout"][aria-pressed="false"] .ot-mode-block > :last-child { opacity: 0; inline-size: 0; }
  .ot-mode[data-variant="knockout"][aria-pressed="false"]:is(:hover, [data-force~="hover"]) .ot-mode-block { --fall: 0.14; }
  .ot-mode[data-variant="knockout"][aria-pressed="true"]:is(:hover, [data-force~="hover"]) .ot-mode-block { --fall: 0.86; }
  .ot-mode[data-variant="knockout"]:disabled .ot-mode-block::before { background: var(--ot-pencil); }

  /* hour: after the numbers used as data in "the silence that heals". Noon by day, midnight at night: 12:00 and 00:00, the hour
     yours in the italic and the minutes ours in pencil. A clock only goes forward, so whichever way you choose the hour turns
     forward: out at the top, in from below, the units first and the tens one step behind, like a carry. */
  .ot-mode[data-variant="hour"] { align-items: baseline; vertical-align: baseline; }
  .ot-mode-hour { display: inline-flex; align-items: baseline; direction: ltr; unicode-bidi: isolate; font-variant-numeric: tabular-nums lining-nums; line-height: 1; }
  .ot-mode-digit {
    display: inline-grid; overflow: clip; padding-block: 0.1em; margin-block: -0.1em;
    font-family: var(--ot-expression); font-style: italic; font-size: calc(var(--ot-expression-scale) * 1em); color: var(--ot-ink);
  }
  .ot-mode-digit > * { grid-area: 1 / 1; text-align: center; }
  .ot-mode-min { margin-inline-start: 0.04em; color: var(--ot-pencil); transition: color var(--ot-allegro); }
  .ot-mode[data-variant="hour"]:is(:hover, [data-force~="hover"]) .ot-mode-min { color: var(--ot-ink); }
  .ot-mode[aria-pressed="false"] .ot-mode-digit > :last-child, .ot-mode[aria-pressed="true"] .ot-mode-digit > :first-child { opacity: 0; translate: 0 -110%; }
  .ot-mode[data-turned][aria-pressed="true"] .ot-mode-digit > :last-child { animation: ot-hour-in var(--ot-moderato) var(--ot-exhale) backwards; }
  .ot-mode[data-turned][aria-pressed="true"] .ot-mode-digit > :first-child { animation: ot-hour-out var(--ot-allegro) var(--ot-breath) backwards; }
  .ot-mode[data-turned][aria-pressed="false"] .ot-mode-digit > :first-child { animation: ot-hour-in-again var(--ot-moderato) var(--ot-exhale) backwards; }
  .ot-mode[data-turned][aria-pressed="false"] .ot-mode-digit > :last-child { animation: ot-hour-out-again var(--ot-allegro) var(--ot-breath) backwards; }
  .ot-mode[data-turned] .ot-mode-digit:first-child > * { animation-delay: calc(var(--ot-arpeggio) * 3); }
  @keyframes ot-hour-in { from { opacity: 0; translate: 0 110%; } to { opacity: 1; translate: 0 0; } }
  @keyframes ot-hour-in-again { from { opacity: 0; translate: 0 110%; } to { opacity: 1; translate: 0 0; } }
  @keyframes ot-hour-out { from { opacity: 1; translate: 0 0; } to { opacity: 0; translate: 0 -110%; } }
  @keyframes ot-hour-out-again { from { opacity: 1; translate: 0 0; } to { opacity: 0; translate: 0 -110%; } }

  /* stop: after the calendar's month set over its year, and the full stop in "Renaissance.". Day over Night, flush to the
     end, and the full stop after the one you read by: the other word steps back to pencil. Choosing sets the stop from Day
     down to Night, or raises it back, one line, landing with spiccato. Pointing pencils a ring where it would go. */
  .ot-mode[data-variant="stop"] .ot-mode-art {
    --s: max(0.34em, 4px);
    display: grid; justify-items: end; white-space: nowrap; line-height: 1.15;
    padding-inline-end: calc(var(--s) + 0.14em);
  }
  .ot-mode[data-variant="stop"] .ot-mode-art > span { color: var(--ot-pencil); transition: color var(--ot-allegro) var(--ot-breath); }
  .ot-mode[data-variant="stop"][aria-checked="false"] .ot-mode-art > [data-for="day"],
  .ot-mode[data-variant="stop"][aria-checked="true"] .ot-mode-art > [data-for="nocturne"] { color: var(--ot-ink); }
  .ot-mode[data-variant="stop"]:is(:hover, [data-force~="hover"]) .ot-mode-art > span { color: var(--ot-graphite); }
  .ot-mode[data-variant="stop"][aria-checked="false"]:is(:hover, [data-force~="hover"]) .ot-mode-art > [data-for="day"],
  .ot-mode[data-variant="stop"][aria-checked="true"]:is(:hover, [data-force~="hover"]) .ot-mode-art > [data-for="nocturne"] { color: var(--ot-ink); }
  .ot-mode[data-variant="stop"] .ot-mode-art::before, .ot-mode[data-variant="stop"] .ot-mode-art::after {
    inset-inline-end: 0; top: calc(0.9em - var(--s)); width: var(--s); height: var(--s); border-radius: 50%; box-sizing: border-box;
  }
  .ot-mode[data-variant="stop"] .ot-mode-art::after { background: var(--ot-ink); transition: translate var(--ot-moderato) var(--ot-spiccato); }
  .ot-mode[data-variant="stop"][aria-checked="true"] .ot-mode-art::after { translate: 0 1lh; }
  .ot-mode[data-variant="stop"] .ot-mode-art::before {
    border: var(--ot-hairline) solid var(--ot-pencil); translate: 0 1lh; opacity: 0;
    transition: opacity var(--ot-allegro) var(--ot-breath);
  }
  .ot-mode[data-variant="stop"][aria-checked="true"] .ot-mode-art::before { translate: none; }
  .ot-mode[data-variant="stop"]:is(:hover, [data-force~="hover"]):not([data-rested]) .ot-mode-art::before { opacity: 1; }

  /* dimmer: a lamp's fader, in one word. Night stands in pencil while it is day; choosing it brings the ink up through the
     letters in reading order, and choosing day lowers it back from the last. Pointing moves the fader one notch: the letter
     that would change first (N by day, t at night) already stands at the other level. */
  .ot-mode[data-variant="dimmer"] .ot-mode-art { white-space: nowrap; direction: ltr; unicode-bidi: isolate; }
  .ot-mode[data-variant="dimmer"] .ot-mode-art > span {
    color: var(--ot-pencil);
    transition: color var(--ot-allegro) var(--ot-breath) calc((4 - var(--i)) * var(--ot-arpeggio));
  }
  .ot-mode[data-variant="dimmer"][aria-checked="true"] .ot-mode-art > span { color: var(--ot-ink); transition-delay: calc(var(--i) * var(--ot-arpeggio)); }
  .ot-mode[data-variant="dimmer"][aria-checked="false"]:is(:hover, [data-force~="hover"]):not([data-rested]) .ot-mode-art > :first-child { color: var(--ot-ink); transition-delay: 0s; }
  .ot-mode[data-variant="dimmer"][aria-checked="true"]:is(:hover, [data-force~="hover"]):not([data-rested]) .ot-mode-art > :last-child { color: var(--ot-pencil); transition-delay: 0s; }

  /* noon: Noon and Moon are one letter apart, so only the initial changes; oon never moves. The N sets below the line and the M
     comes down from above as night falls, and back at dawn, the way the page itself changes. Tabular in spirit: the initial's
     cell is as wide as the M, so the word keeps its place. */
  .ot-mode[data-variant="noon"] .ot-mode-art { white-space: nowrap; direction: ltr; unicode-bidi: isolate; }
  .ot-mode-initial { display: inline-grid; justify-items: end; overflow: clip; padding-block: 0.12em 0.24em; margin-block: -0.12em -0.24em; }
  .ot-mode-initial > span { grid-area: 1 / 1; transition: translate var(--ot-allegro) var(--ot-breath), opacity var(--ot-allegro) var(--ot-breath); }
  /* One letter at a time: the old initial leaves, then the new one lands, never both half in the cell. */
  .ot-mode[aria-checked="false"] .ot-mode-initial > :first-child,
  .ot-mode[aria-checked="true"] .ot-mode-initial > :last-child { transition-delay: calc(var(--ot-arpeggio) * 3); transition-timing-function: var(--ot-exhale); }
  .ot-mode[aria-checked="false"] .ot-mode-initial > :last-child { translate: 0 -110%; opacity: 0; }
  .ot-mode[aria-checked="true"] .ot-mode-initial > :first-child { translate: 0 110%; opacity: 0; }

  /* In a bar, the switch keeps a finger-sized target without growing the row. */
  .ot-mode[data-scene].bar-mode { min-block-size: 44px; flex: none; }

  /* Scene changes, one for each switch: the appearance hook passes data-scene as the View Transition's type. The body's own
     colour transition is off for them, so the new sheet is final at once. Nothing is caught by the overlay. */
  :root:active-view-transition-type(ot-dissolve, ot-dim, ot-fall) body { transition: none; }
  :root:active-view-transition-type(ot-dissolve, ot-dim, ot-fall)::view-transition { pointer-events: none; }
  :root:active-view-transition-type(ot-dissolve, ot-dim, ot-fall)::view-transition-old(root) { animation: none; }
  /* dissolve: the new sheet comes up through the old at the press's own tempo (allegro), so the grey middle is only a glance
     and the stop lands after the page has turned. */
  :root:active-view-transition-type(ot-dissolve)::view-transition-new(root) { animation: ot-mode-dissolve var(--ot-allegro) var(--ot-breath) both; }
  @keyframes ot-mode-dissolve { from { opacity: 0; } }
  /* dim: a light lowered. Going to night the day sheet dims, and the night comes up through it; going to day the day sheet
     arrives dim and its light is raised. Either way the page passes through the same dimmed day. */
  :root[data-mode="nocturne"]:active-view-transition-type(ot-dim)::view-transition-old(root) { animation: ot-mode-lower var(--ot-moderato) var(--ot-breath) both; }
  :root[data-mode="nocturne"]:active-view-transition-type(ot-dim)::view-transition-new(root) { animation: ot-mode-dissolve var(--ot-moderato) cubic-bezier(.5, 0, .75, 0) both; }
  :root:not([data-mode="nocturne"]):active-view-transition-type(ot-dim)::view-transition-new(root) { animation: ot-mode-raise var(--ot-moderato) var(--ot-breath) both; }
  @keyframes ot-mode-lower { to { filter: brightness(0.12); } }
  @keyframes ot-mode-raise { from { opacity: 0; filter: brightness(0.12); } 40% { opacity: 1; } }
  /* fall: the new sheet comes down over the page from the top edge, where the switch is, on one straight line, moderato. Both
     ways: the answer starts at the press and reads down the page in reading order. */
  :root:active-view-transition-type(ot-fall)::view-transition-new(root) { animation: ot-mode-fall var(--ot-moderato) var(--ot-breath) both; }
  @keyframes ot-mode-fall { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0); } }

  /* Reduced motion: the hook changes the page at once, the tempi are 1ms, and a documentation row can pin it. */
  .ot-mode[data-force~="reduced"], .ot-mode[data-force~="reduced"] * { transition: none; }
  .ot-mode[data-force~="reduced"] .ot-mode-art::before, .ot-mode[data-force~="reduced"] .ot-mode-art::after { transition: none; }

  /* Forced colours drop backgrounds and masks' colours: say what each part is. */
  @media (forced-colors: active) {
    .ot-mode { color: ButtonText; }
    .ot-mode:is([data-variant="stop"], [data-variant="dimmer"]) { --ot-ink: ButtonText; --ot-graphite: ButtonText; --ot-pencil: GrayText; }
    .ot-mode:focus-visible, .ot-mode[data-force~="focus"] { outline-color: Highlight; }
    .ot-mode-art::before, .ot-mode-art::after, .ot-mode-roll, .ot-mode-state { forced-color-adjust: none; }
    .ot-mode[data-variant="eclipse"] .ot-mode-art::before, .ot-mode[data-variant="fermata"] .ot-mode-art::after { background: ButtonText; }
    .ot-mode-roll, .ot-mode-state { color: ButtonText; background-image: linear-gradient(ButtonText, ButtonText); }
    .ot-mode-block, .ot-mode-block::before, .ot-mode-digit, .ot-mode-min { forced-color-adjust: none; color: ButtonText; }
    .ot-mode-block::before { background: ButtonText; }
    .ot-mode[aria-pressed="true"] .ot-mode-block { color: ButtonFace; }
    .ot-mode[data-variant="stop"] .ot-mode-art > span, .ot-mode[data-variant="dimmer"] .ot-mode-art > span { forced-color-adjust: none; }
    .ot-mode[data-variant="stop"] .ot-mode-art::after { background: ButtonText; }
    .ot-mode[data-variant="stop"] .ot-mode-art::before { border-color: ButtonText; }
    .ot-mode[data-variant="stop"] .ot-mode-art > span, .ot-mode[data-variant="dimmer"][aria-checked="false"] .ot-mode-art > span { color: GrayText; }
    .ot-mode[data-variant="stop"][aria-checked="false"] .ot-mode-art > [data-for="day"],
    .ot-mode[data-variant="stop"][aria-checked="true"] .ot-mode-art > [data-for="nocturne"],
    .ot-mode[data-variant="dimmer"][aria-checked="true"] .ot-mode-art > span { color: ButtonText; }
  }
}
